import{createAccount,createClient}from'https://esm.sh/genlayer-js@1.1.8';import{studionet}from'https://esm.sh/genlayer-js@1.1.8/chains';
const CONTRACT='0x90507eB04c75D79378eEFA95b7B4e530e74f5d03',endpoint='https://studio.genlayer.com/api',repo='https://raw.githubusercontent.com/sanshos1/caption-lantern/main/evidence/';
const $=id=>document.getElementById(id),reader=createClient({chain:studionet,endpoint,account:createAccount()});let writer=null,state='DRAFT';
$('reelId').value='LANTERN-'+Date.now();$('transcript').value=repo+'demo-transcript.txt';$('captions').value=repo+'demo-captions.vtt';$('standard').value=repo+'demo-standard.txt';$('patch').value=repo+'demo-patch.vtt';$('explorer').href=CONTRACT.startsWith('0x')?`https://explorer-studio.genlayer.com/address/${CONTRACT}`:'#';
const say=x=>$('message').textContent=x;const short=x=>x.slice(0,6)+'…'+x.slice(-4);$('begin').onclick=()=>document.querySelector('#screening').scrollIntoView();$('sourcesToggle').onclick=()=>{const d=$('sourceDrawer');d.hidden=!d.hidden;$('sourcesToggle').textContent=d.hidden?'OPEN SOURCE DRAWER':'CLOSE SOURCE DRAWER'};
async function connect(){const p=window.ethereum;if(!p)throw Error('Install MetaMask or Rabby to continue.');const[a]=await p.request({method:'eth_requestAccounts'});if((await p.request({method:'eth_chainId'})).toLowerCase()!=='0xf22f')await p.request({method:'wallet_switchEthereumChain',params:[{chainId:'0xf22f'}]});writer=createClient({chain:studionet,endpoint,account:a,provider:p});$('connect').textContent=short(a);say('Wallet connected. The reel can now be mounted.')} $('connect').onclick=()=>connect().catch(e=>say(e.message));
async function write(name,args){if(!CONTRACT.startsWith('0x'))throw Error('Contract deployment has not been inserted yet.');if(!writer)throw Error('Connect wallet first.');const hash=await writer.writeContract({address:CONTRACT,functionName:name,args,value:0n});say(`Transaction submitted ${short(hash)}. Waiting for validator acceptance…`);await writer.waitForTransactionReceipt({hash,status:'ACCEPTED',retries:120,interval:5000});say(`Accepted ${short(hash)}. Waiting for finalization…`);await writer.waitForTransactionReceipt({hash,status:'FINALIZED',retries:180,interval:5000});return hash}
function mark(a){const audit=a.audit||a;$('coverage').textContent=(audit.coverage??'--')+'%';$('verdict').textContent=audit.verdict||'WAITING FOR A SCREENING';$('stageLabel').textContent=audit.source_round==='PATCH'?'PATCH SCREENING':'ORIGINAL SCREENING';const flags=new Set((audit.cue_indexes||[]).map(Number));document.querySelectorAll('[data-cue]').forEach((b,i)=>b.classList.toggle('flag',flags.has(i)));$('frameText').textContent=audit.rationale||'No stored rationale yet.'}
$('mount').onclick=async()=>{try{const id=$('reelId').value.trim();await write('mount_reel',[id,$('title').value.trim(),$('language').value.trim(),$('transcript').value.trim(),$('captions').value.trim(),$('standard').value.trim()]);state='OPEN';$('mount').disabled=true;$('audit').disabled=false;$('stageLabel').textContent='REEL MOUNTED';say('Reel finalized on StudioNet. Light it when ready.')}catch(e){say(e.message||String(e))}};
$('audit').onclick=async()=>{try{await write('light_reel',[$('reelId').value.trim()]);const r=await reader.readContract({address:CONTRACT,functionName:'get_reel',args:[$('reelId').value.trim()]});mark(r);state='AUDITED';$('audit').disabled=true;$('repair').disabled=false;say('Original screening finalized and read back from the contract.')}catch(e){say(e.message||String(e))}};
$('repair').onclick=async()=>{try{await write('mount_patch',[$('reelId').value.trim(),$('patch').value.trim()]);const r=await reader.readContract({address:CONTRACT,functionName:'get_reel',args:[$('reelId').value.trim()]});mark(r);state='PATCHED';$('repair').disabled=true;say('Repair screening finalized. The cue sheet now reflects the patched track.')}catch(e){say(e.message||String(e))}};
document.querySelectorAll('[data-cue]').forEach((b,i)=>b.onclick=()=>{$('frameTime').textContent='00:00:'+(b.textContent||'00');$('frameText').textContent=['The doors open at seven.','[Soft bell rings]','MAYA: Use the east entrance after sunset.','NARRATOR: Staff can provide a portable ramp.','[Footsteps move from left to right]','MAYA: Ask at the lantern desk if you need assistance.'][i]});
